def _check_docstring(self, node_type, node, report_missing=True, confidence=interfaces.HIGH):
    docstring = node.doc
    if docstring is None:
        if not report_missing:
            return
        lines = utils.get_node_last_lineno(node) - node.lineno
        if node_type == "module" and not lines:
            # If the module has no body, there's no reason to require a docstring.
            return
        max_lines = self.config.docstring_min_length
        if node_type != "module" and max_lines > -1 and lines < max_lines:
            self.stats["undocumented_" + node_type] += 1
        if (node.body and isinstance(node.body[0], astroid.Expr) and isinstance(node.body[0].value, astroid.Call)):
            # Most likely a string with a format call. Let's see.
            func = utils.safe_infer(node.body[0].value.func)
            if isinstance(func, astroid.BoundMethod) and isinstance(func.bound, astroid.Instance):
                # Strings in Python 3, others in Python 2.
                if PY3K and func.bound.name == "str":
                    return
                if func.bound.name in ("str", "unicode", "bytes"):
                    return self.add_message("missing-docstring", node=node, args=(node_type,), confidence=confidence)
        elif not docstring.strip():
            self.stats["undocumented_" + node_type] += 1
            self.add_message("empty-docstring", node=node, args=(node_type,), confidence=confidence)

So the method checks if a node (module, class, function, etc.) has a docstring. If missing, it may add a message "missing-docstring" or "empty-docstring". It also updates stats. It handles special cases: modules with no body, docstring length less than min length, string formatting calls, etc.

