def deobfuscate(request, key, juice=None):
    try:
        url = decrypt(str(key), settings.UNFRIENDLY_SECRET, settings.UNFRIENDLY_IV, checksum=settings.UNFRIENDLY_ENFORCE_CHECKSUM)
    except (CheckSumError, InvalidKeyError):
        return HttpResponseNotFound()
    try:
        url = url.decode('utf-8')
    except UnicodeDecodeError:
        return HttpResponseNotFound()
    url_parts = urlparse(unquote(url))
    path = url_parts.path
    query = url_parts.query
    try:
        view, args, kwargs = resolve(path)
    except Resolver404:
        return HttpResponseNotFound()
    # fix-up environ
    environ = request.environ.copy()
    environ['PATH_INFO'] = path[len(environ['SCRIPT_NAME']):]
    environ['QUERY_STRING'] = query
    # init a new request patched_request = request.__class__(environ)
    # copy over any missing request attributes - hackish
    missing_items = set(dir(request)) - set(dir(patched_request))
    while missing_items:
        missing_item = missing_items.pop()
        patched_request.__setattr__(missing_item, request.__getattribute__(missing_item))
    # mark this request as obfuscated
    patched_request.META['obfuscated'] = True
    response = view(patched_request, *args, **kwargs)
    # offer up a friendlier juice-powered filename if downloaded
    if juice and not response.has_header('Content-Disposition'):
        response['Content-Disposition'] = 'inline; filename=%s' % juice
    return response

So the function decrypts a key to get a URL, resolves it to a view, creates a new request with that path and query, copies missing attributes, marks as obfuscated, calls the view, optionally sets Content-Disposition header if juice provided, returns response. If any errors, returns 404.

